    [Theory]
    [MemberData(nameof(Mistakes))]
    public void OperandsTakenTheWrongWayRoundAreFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The evaluators the right way round; the value taken first named the right-hand one; only adding and multiplying,
    /// where the order does not matter; the tops of two stacks compared, one taken off each; and two values taken from the
    /// front of a queue.
    /// </summary>
    [Theory]
    [InlineData("Program.cs", "using System;\nusing System.Collections.Generic;\n\npublic static class Program\n{\n    static int Evaluate(string[] tokens)\n    {\n        var stack = new Stack<int>();\n        foreach (var token in tokens)\n        {\n            if (int.TryParse(token, out var number))\n            {\n                stack.Push(number);\n                continue;\n            }\n\n            var right = stack.Pop();\n            var left = stack.Pop();\n            stack.Push(token switch\n            {\n                \"+\" => left + right,\n                \"-\" => left - right,\n                _ => left * right,\n            });\n        }\n\n        return stack.Pop();\n    }\n\n    public static void Main()\n    {\n        Console.WriteLine($\"{Evaluate([\"10\", \"2\", \"-\", \"3\", \"-\"])} {Evaluate([\"2\", \"3\", \"4\", \"*\", \"-\"])}\");\n    }\n}\n")]
    [InlineData("rpn.c", "#include <stdio.h>\n#include <stdlib.h>\n\nstatic int evaluate(const char *tokens[], int count) {\n    int stack[16];\n    int top = 0;\n    for (int i = 0; i < count; i++) {\n        const char *token = tokens[i];\n        if (token[0] != '+' && token[0] != '-' && token[0] != '*') {\n            stack[top++] = atoi(token);\n            continue;\n        }\n        int b = stack[--top];\n        int a = stack[--top];\n        switch (token[0]) {\n        case '+': stack[top++] = a + b; break;\n        case '-': stack[top++] = a - b; break;\n        default: stack[top++] = a * b; break;\n        }\n    }\n    return stack[--top];\n}\n\nint main(void) {\n    const char *first[] = {\"10\", \"2\", \"-\", \"3\", \"-\"};\n    const char *second[] = {\"2\", \"3\", \"4\", \"*\", \"-\"};\n    printf(\"%d %d\\n\", evaluate(first, 5), evaluate(second, 5));\n    return 0;\n}\n")]
    [InlineData("rpn.cpp", "#include <iostream>\n#include <string>\n#include <vector>\n\nint evaluate(const std::vector<std::string>& tokens) {\n    std::vector<int> stack;\n    for (const std::string& token : tokens) {\n        if (token != \"+\" && token != \"-\" && token != \"*\") {\n            stack.push_back(std::stoi(token));\n            continue;\n        }\n        int b = stack.back();\n        stack.pop_back();\n        int a = stack.back();\n        stack.pop_back();\n        if (token == \"+\") stack.push_back(a + b);\n        else if (token == \"-\") stack.push_back(a - b);\n        else stack.push_back(a * b);\n    }\n    return stack.back();\n}\n\nint main() {\n    std::cout << evaluate({\"10\", \"2\", \"-\", \"3\", \"-\"}) << \" \" << evaluate({\"2\", \"3\", \"4\", \"*\", \"-\"}) << std::endl;\n    return 0;\n}\n")]
    [InlineData("rpn.dart", "int evaluate(List<String> tokens) {\n  final stack = <int>[];\n  for (final token in tokens) {\n    final number = int.tryParse(token);\n    if (number != null) {\n      stack.add(number);\n      continue;\n    }\n    final b = stack.removeLast();\n    final a = stack.removeLast();\n    switch (token) {\n      case '+':\n        stack.add(a + b);\n      case '-':\n        stack.add(a - b);\n      default:\n        stack.add(a * b);\n    }\n  }\n  return stack.removeLast();\n}\n\nvoid main() {\n  print('${evaluate(['10', '2', '-', '3', '-'])} ${evaluate(['2', '3', '4', '*', '-'])}');\n}\n")]
    [InlineData("rpn.erl", "-module(rpn).\n-export([main/0]).\n\nstep(\"+\", [A, B | Rest]) -> [A + B | Rest];\nstep(\"-\", [B, A | Rest]) -> [A - B | Rest];\nstep(\"*\", [A, B | Rest]) -> [A * B | Rest];\nstep(Number, Stack) -> [list_to_integer(Number) | Stack].\n\nevaluate(Tokens) -> hd(lists:foldl(fun(Token, Stack) -> step(Token, Stack) end, [], Tokens)).\n\nmain() ->\n    io:format(\"~p ~p~n\", [evaluate([\"10\", \"2\", \"-\", \"3\", \"-\"]), evaluate([\"2\", \"3\", \"4\", \"*\", \"-\"])]).\n")]
    [InlineData("rpn.exs", "defmodule Rpn do\n  def evaluate(tokens), do: tokens |> Enum.reduce([], &step/2) |> hd()\n\n  defp step(\"+\", [a, b | rest]), do: [a + b | rest]\n  defp step(\"-\", [b, a | rest]), do: [a - b | rest]\n  defp step(\"*\", [a, b | rest]), do: [a * b | rest]\n  defp step(number, stack), do: [String.to_integer(number) | stack]\nend\n\nIO.puts(\"#{Rpn.evaluate(~w(10 2 - 3 -))} #{Rpn.evaluate(~w(2 3 4 * -))}\")\n")]
    [InlineData("rpn.f90", "module rpn_module\n  implicit none\ncontains\n  integer function evaluate(tokens)\n    character(len=*), intent(in) :: tokens(:)\n    integer :: stack(16), top, i, a, b\n    top = 0\n    do i = 1, size(tokens)\n      select case (trim(tokens(i)))\n      case ('+', '-', '*')\n        b = stack(top)\n        top = top - 1\n        a = stack(top)\n        top = top - 1\n        top = top + 1\n        select case (trim(tokens(i)))\n        case ('+')\n          stack(top) = a + b\n        case ('-')\n          stack(top) = a - b\n        case default\n          stack(top) = a * b\n        end select\n      case default\n        top = top + 1\n        read (tokens(i), *) stack(top)\n      end select\n    end do\n    evaluate = stack(top)\n  end function evaluate\nend module rpn_module\n\nprogram rpn_program\n  use rpn_module\n  implicit none\n  character(len=2) :: first(5) = ['10', '2 ', '- ', '3 ', '- ']\n  character(len=2) :: second(5) = ['2 ', '3 ', '4 ', '* ', '- ']\n  print '(I0, 1X, I0)', evaluate(first), evaluate(second)\nend program rpn_program\n")]
    [InlineData("rpn.fsx", "let step stack token =\n    match token, stack with\n    | \"+\", a :: b :: rest -> (a + b) :: rest\n    | \"-\", b :: a :: rest -> (a - b) :: rest\n    | \"*\", a :: b :: rest -> (a * b) :: rest\n    | number, rest -> int number :: rest\n\nlet evaluate tokens = List.fold step [] tokens |> List.head\n\nprintfn \"%d %d\" (evaluate [ \"10\"; \"2\"; \"-\"; \"3\"; \"-\" ]) (evaluate [ \"2\"; \"3\"; \"4\"; \"*\"; \"-\" ])\n")]
    [InlineData("rpn.go", "package main\n\nimport (\n\t\"fmt\"\n\t\"strconv\"\n)\n\nfunc evaluate(tokens []string) int {\n\tvar stack []int\n\tfor _, token := range tokens {\n\t\tnumber, err := strconv.Atoi(token)\n\t\tif err == nil {\n\t\t\tstack = append(stack, number)\n\t\t\tcontinue\n\t\t}\n\t\tb := stack[len(stack)-1]\n\t\tstack = stack[:len(stack)-1]\n\t\ta := stack[len(stack)-1]\n\t\tstack = stack[:len(stack)-1]\n\t\tswitch token {\n\t\tcase \"+\":\n\t\t\tstack = append(stack, a+b)\n\t\tcase \"-\":\n\t\t\tstack = append(stack, a-b)\n\t\tdefault:\n\t\t\tstack = append(stack, a*b)\n\t\t}\n\t}\n\treturn stack[0]\n}\n\nfunc main() {\n\tfmt.Println(evaluate([]string{\"10\", \"2\", \"-\", \"3\", \"-\"}), evaluate([]string{\"2\", \"3\", \"4\", \"*\", \"-\"}))\n}\n")]
    [InlineData("rpn.js", "function evaluate(tokens) {\n  const stack = [];\n  for (const token of tokens) {\n    if (!isNaN(Number(token))) {\n      stack.push(Number(token));\n      continue;\n    }\n    const b = stack.pop();\n    const a = stack.pop();\n    if (token === \"+\") stack.push(a + b);\n    else if (token === \"-\") stack.push(a - b);\n    else stack.push(a * b);\n  }\n  return stack.pop();\n}\n\nconsole.log(evaluate([\"10\", \"2\", \"-\", \"3\", \"-\"]), evaluate([\"2\", \"3\", \"4\", \"*\", \"-\"]));\n")]
    [InlineData("rpn.lua", "local function evaluate(tokens)\n  local stack = {}\n  for _, token in ipairs(tokens) do\n    local number = tonumber(token)\n    if number then\n      stack[#stack + 1] = number\n    else\n      local b = table.remove(stack)\n      local a = table.remove(stack)\n      if token == \"+\" then\n        stack[#stack + 1] = a + b\n      elseif token == \"-\" then\n        stack[#stack + 1] = a - b\n      else\n        stack[#stack + 1] = a * b\n      end\n    end\n  end\n  return table.remove(stack)\nend\n\nprint(evaluate({ \"10\", \"2\", \"-\", \"3\", \"-\" }) .. \" \" .. evaluate({ \"2\", \"3\", \"4\", \"*\", \"-\" }))\n")]
    [InlineData("rpn.ml", "let step stack token =\n  match token, stack with\n  | \"+\", a :: b :: rest -> (a + b) :: rest\n  | \"-\", b :: a :: rest -> (a - b) :: rest\n  | \"*\", a :: b :: rest -> (a * b) :: rest\n  | number, rest -> int_of_string number :: rest\n\nlet evaluate tokens = List.hd (List.fold_left step [] tokens)\n\nlet () = Printf.printf \"%d %d\\n\" (evaluate [ \"10\"; \"2\"; \"-\"; \"3\"; \"-\" ]) (evaluate [ \"2\"; \"3\"; \"4\"; \"*\"; \"-\" ])\n")]
    [InlineData("rpn.php", "<?php\nfunction evaluate(array $tokens): int {\n    $stack = [];\n    foreach ($tokens as $token) {\n        if (is_numeric($token)) {\n            $stack[] = (int) $token;\n            continue;\n        }\n        $b = array_pop($stack);\n        $a = array_pop($stack);\n        $stack[] = match ($token) {\n            '+' => $a + $b,\n            '-' => $a - $b,\n            default => $a * $b,\n        };\n    }\n    return array_pop($stack);\n}\n\necho evaluate([\"10\", \"2\", \"-\", \"3\", \"-\"]), \" \", evaluate([\"2\", \"3\", \"4\", \"*\", \"-\"]), \"\\n\";\n")]
    [InlineData("rpn.pl", "use strict;\nuse warnings;\n\nsub evaluate {\n    my @stack;\n    for my $token (@_) {\n        if ($token =~ /^-?\\d+$/) {\n            push @stack, $token;\n            next;\n        }\n        my $y = pop @stack;\n        my $x = pop @stack;\n        if ($token eq \"+\") { push @stack, $x + $y }\n        elsif ($token eq \"-\") { push @stack, $x - $y }\n        else { push @stack, $x * $y }\n    }\n    return pop @stack;\n}\n\nprint join(\" \", evaluate(qw(10 2 - 3 -)), evaluate(qw(2 3 4 * -))), \"\\n\";\n")]
    [InlineData("rpn.ps1", "function Measure-Rpn([string[]]$tokens) {\n    $stack = [System.Collections.Generic.Stack[int]]::new()\n    foreach ($token in $tokens) {\n        if ($token -match '^-?\\d+$') {\n            $stack.Push([int]$token)\n            continue\n        }\n        $b = $stack.Pop()\n        $a = $stack.Pop()\n        switch ($token) {\n            '+' { $stack.Push($a + $b) }\n            '-' { $stack.Push($a - $b) }\n            default { $stack.Push($a * $b) }\n        }\n    }\n    return $stack.Pop()\n}\n\n\"$(Measure-Rpn @('10', '2', '-', '3', '-')) $(Measure-Rpn @('2', '3', '4', '*', '-'))\"\n")]
    [InlineData("rpn.rb", "def evaluate(tokens)\n  stack = []\n  tokens.each do |token|\n    if token =~ /\\A-?\\d+\\z/\n      stack.push(token.to_i)\n      next\n    end\n    b = stack.pop\n    a = stack.pop\n    stack.push(case token\n               when \"+\" then a + b\n               when \"-\" then a - b\n               else a * b\n               end)\n  end\n  stack.pop\nend\n\nputs \"#{evaluate(%w[10 2 - 3 -])} #{evaluate(%w[2 3 4 * -])}\"\n")]
    [InlineData("rpn.rs", "fn evaluate(tokens: &[&str]) -> i32 {\n    let mut stack: Vec<i32> = Vec::new();\n    for token in tokens {\n        if let Ok(number) = token.parse::<i32>() {\n            stack.push(number);\n            continue;\n        }\n        let b = stack.pop().unwrap();\n        let a = stack.pop().unwrap();\n        stack.push(match *token {\n            \"+\" => a + b,\n            \"-\" => a - b,\n            _ => a * b,\n        });\n    }\n    stack.pop().unwrap()\n}\n\nfn main() {\n    println!(\"{} {}\", evaluate(&[\"10\", \"2\", \"-\", \"3\", \"-\"]), evaluate(&[\"2\", \"3\", \"4\", \"*\", \"-\"]));\n}\n")]
    [InlineData("Rpn.scala", "import scala.collection.mutable\n\nobject Rpn {\n  def evaluate(tokens: Seq[String]): Int = {\n    val stack = mutable.Stack[Int]()\n    for (token <- tokens) {\n      token.toIntOption match {\n        case Some(number) => stack.push(number)\n        case None =>\n          val b = stack.pop()\n          val a = stack.pop()\n          stack.push(token match {\n            case \"+\" => a + b\n            case \"-\" => a - b\n            case _ => a * b\n          })\n      }\n    }\n    stack.pop()\n  }\n\n  def main(args: Array[String]): Unit =\n    println(s\"${evaluate(Seq(\"10\", \"2\", \"-\", \"3\", \"-\"))} ${evaluate(Seq(\"2\", \"3\", \"4\", \"*\", \"-\"))}\")\n}\n")]
    [InlineData("rpn.ts", "const operations: Record<string, (x: number, y: number) => number> = {\n  \"+\": (x, y) => x + y,\n  \"-\": (x, y) => x - y,\n  \"*\": (x, y) => x * y,\n};\n\nfunction evaluate(tokens: string[]): number {\n  const stack: number[] = [];\n  for (const token of tokens) {\n    if (token in operations) {\n      const a = stack.pop()!;\n      const b = stack.pop()!;\n      stack.push(operations[token](b, a));\n    } else {\n      stack.push(Number(token));\n    }\n  }\n  return stack.pop()!;\n}\n\nconsole.log(evaluate([\"10\", \"2\", \"-\", \"3\", \"-\"]), evaluate([\"2\", \"3\", \"4\", \"*\", \"-\"]));\n")]
    [InlineData("rpn_eval.py", "def rpn_eval(tokens):\n    def op(symbol, a, b):\n        return {\n            '+': lambda a, b: a + b,\n            '-': lambda a, b: a - b,\n            '*': lambda a, b: a * b,\n            '/': lambda a, b: a / b\n        }[symbol](a, b)\n\n    stack = []\n\n    for token in tokens:\n        if isinstance(token, int):\n            stack.append(token)\n        else:\n            a = stack.pop()\n            b = stack.pop()\n            stack.append(\n                op(token, b, a)\n            )\n\n    return stack.pop()\n\n\nprint(rpn_eval([10, 2, '-', 3, '-']), rpn_eval([2, 3, 4, '*', '-']))\n")]
    [InlineData("RpnEval.java", "import java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Stack;\nimport java.util.function.BinaryOperator;\n\npublic class RpnEval {\n    public static Integer rpn_eval(List<Object> tokens) {\n        Map<String, BinaryOperator<Integer>> op = new HashMap<String, BinaryOperator<Integer>>();\n        op.put(\"+\", (a, b) -> a + b);\n        op.put(\"-\", (a, b) -> a - b);\n        op.put(\"*\", (a, b) -> a * b);\n        Stack<Integer> stack = new Stack<Integer>();\n        for (Object token : tokens) {\n            if (token instanceof Integer) {\n                stack.push((Integer) token);\n            } else {\n                Integer a = stack.pop();\n                Integer b = stack.pop();\n                BinaryOperator<Integer> bin_op = op.get(token);\n                Integer c = bin_op.apply(b,a);\n                stack.push(c);\n            }\n        }\n        return stack.pop();\n    }\n\n    public static void main(String[] args) {\n        System.out.println(rpn_eval(List.of(10, 2, \"-\", 3, \"-\")) + \" \" + rpn_eval(List.of(2, 3, 4, \"*\", \"-\")));\n    }\n}\n")]
    [InlineData("named_right_first.py", "# The value taken first named the right-hand one: prints 5 -10.\ndef evaluate(tokens):\n    stack = []\n    for token in tokens:\n        if isinstance(token, int):\n            stack.append(token)\n            continue\n        right = stack.pop()\n        left = stack.pop()\n        stack.append(left - right if token == '-' else left * right)\n    return stack.pop()\n\n\nprint(evaluate([10, 2, '-', 3, '-']), evaluate([2, 3, 4, '*', '-']))\n")]
