    [InlineData("sums_only.js", "// Only adding and multiplying, where the order the two come in does not matter: prints 15 14.\nfunction evaluate(tokens) {\n  const stack = [];\n  for (const token of tokens) {\n    if (token !== \"+\" && token !== \"*\") {\n      stack.push(Number(token));\n      continue;\n    }\n    const a = stack.pop();\n    const b = stack.pop();\n    stack.push(token === \"+\" ? a + b : a * b);\n  }\n  return stack.pop();\n}\n\nconsole.log(evaluate([\"10\", \"2\", \"+\", \"3\", \"+\"]), evaluate([\"2\", \"3\", \"4\", \"+\", \"*\"]));\n")]
